(function(root){
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function bytes(value){const n=Math.max(0,Number(value)||0);if(n<1024)return n+' B';const i=Math.min(3,Math.floor(Math.log(n)/Math.log(1024)));return (n/1024**i).toFixed(1)+' '+['B','KiB','MiB','GiB'][i];}
function summary(data){return '<div class="storage-totals">'+[[data.task_bytes,'Saved task data'],[data.workspace_bytes,'Task copies'],[data.eligible_bytes,'Eligible to reclaim']].map(([n,label])=>'<div><strong>'+bytes(n)+'</strong><span>'+label+'</span></div>').join('')+'</div><p>File sizes on this installation. Task copies are included in saved task data; these totals do not include your source projects or external worktrees.</p>';}
function rows(data){return '<ul class="storage-tasks">'+data.tasks.map(task=>'<li><div><strong>'+esc(task.title)+'</strong><span>'+bytes(task.workspace_bytes)+'</span></div><p>'+esc(task.reason)+'</p></li>').join('')+'</ul>'+(data.tasks.length?'':'<p>No saved tasks yet.</p>');}
async function open({api,dialog,header}){
 const d=dialog(header('THIS INSTALLATION','Storage')+'<p>This installation · applies to all projects and chats.</p><p role="status">Measuring saved task data…</p><p role="alert"></p><div data-storage></div>','storage-settings');
 const q=s=>d.querySelector(s);let data,busy=false,dirty=false;
 const status=text=>{q('[role=status]').textContent=text;};
 function render(){q('[data-storage]').innerHTML=summary(data)+'<form data-policy><label class="storage-toggle"><input type="checkbox" name="reclaim" '+(data.settings.reclaim_merged?'checked':'')+'> Automatically reclaim merged task copies</label><p>Requires a confirmed merge and no unpublished edits. Chat history, saved diffs, reviews, checks and merge details stay available. Unfinished tasks, open PRs and active previews keep their files.</p><label class="scoped-settings-field">Permanently delete Trash after<select name="retention"><option value="">Never (manual Empty Trash only)</option>'+[7,30,90,365].map(n=>'<option value="'+n+'" '+(data.settings.trash_days===n?'selected':'')+'>'+n+' days</option>').join('')+(![null,7,30,90,365].includes(data.settings.trash_days)?'<option selected value="'+data.settings.trash_days+'">'+data.settings.trash_days+' days</option>':'')+'</select></label><p class="storage-warning">Trash expiry permanently deletes the chat, its files and saved evidence. This cannot be undone. Already-expired tasks can be deleted as soon as you save. Lifetime aggregate usage is retained.</p><div class="button-row"><button type="submit">Save storage settings</button><button type="button" data-refresh>Refresh usage</button><button type="button" data-cleanup>Run cleanup now</button></div><p>Cleanup follows your saved settings. Automatic maintenance runs at startup, after merge confirmation, and periodically while the app is open.</p></form><h3>Task copies</h3>'+rows(data);
 q('[data-policy]').onchange=()=>{dirty=true;status('Unsaved storage settings. Save before running cleanup.');q('[data-cleanup]').disabled=true;q('[data-refresh]').disabled=true;};
 q('[data-policy]').onsubmit=e=>{e.preventDefault();const form=q('[data-policy]');act(async()=>{await api('/storage/settings',{reclaim_merged:form.elements.reclaim.checked,trash_days:form.elements.retention.value===''?null:Number(form.elements.retention.value)});dirty=false;await load('Storage settings saved for this installation.');},'Saving storage settings…');};
 q('[data-refresh]').onclick=()=>act(()=>load('Usage refreshed.'),'Measuring saved task data…');
 q('[data-cleanup]').onclick=()=>act(async()=>{const result=await api('/storage/cleanup',{});await load(result.reclaimed+' task copies reclaimed; '+result.deleted+' expired Trash tasks deleted.'+(result.retained?' '+result.retained+' busy tasks retained.':''));if(result.errors?.length)q('[role=alert]').textContent=result.errors.length+' task(s) retained: '+result.errors.map(e=>e.message).join('; ');},'Checking ownership and saved work before cleanup…');
 }
 async function load(message){const result=await api('/storage');if(!d.open)return;data=result;render();status(message);if(data.last_run?.error)q('[role=alert]').textContent=data.last_run.error;}
 async function act(fn,message){if(busy)return;busy=true;status(message);q('[role=alert]').textContent='';d.querySelectorAll('button,input,select').forEach(el=>el.disabled=true);try{await fn();}catch(error){if(d.open)q('[role=alert]').textContent=error.message;}finally{busy=false;if(d.open){d.querySelectorAll('button,input,select').forEach(el=>el.disabled=false);if(dirty){q('[data-cleanup]').disabled=true;q('[data-refresh]').disabled=true;}}}}
 await act(()=>load('Usage measured. Opening this page does not delete anything.'),'Measuring saved task data…');return d;
}
const exported={open,bytes,summary,rows};if(typeof module!=='undefined')module.exports=exported;else root.CheapOSStorage=exported;
})(typeof globalThis!=='undefined'?globalThis:this);
